mapper.select:
SELECT * FROM (
    SELECT t.*, ROWNUM AS RN FROM (
        SELECT * FROM TBL_BUDGET_ANALYSIS_CHART
        WHERE DEL_FLAG = 0

            AND CHART_TYPE = #{chartType}


            AND DATA_SOURCE = #{dataSource}


            AND CREATOR LIKE '%' || #{creator} || '%'


            AND CHART_NAME LIKE '%' || #{chartName} || '%'


            AND STATUS = #{status}


            AND CREATE_TIME >= TO_DATE(#{startTime}, 'YYYY-MM-DD')


            AND CREATE_TIME <= TO_DATE(#{endTime}, 'YYYY-MM-DD') + 1

        ORDER BY CREATE_TIME DESC
    ) t WHERE ROWNUM <= #{endRow}
) WHERE RN > #{startRow}

SELECT COUNT(*) FROM TBL_BUDGET_ANALYSIS_CHART
WHERE DEL_FLAG = 0

    AND CHART_TYPE = #{chartType}


    AND DATA_SOURCE = #{dataSource}


    AND CREATOR LIKE '%' || #{creator} || '%'


    AND CHART_NAME LIKE '%' || #{chartName} || '%'


    AND STATUS = #{status}


    AND CREATE_TIME >= TO_DATE(#{startTime}, 'YYYY-MM-DD')


    AND CREATE_TIME <= TO_DATE(#{endTime}, 'YYYY-MM-DD') + 1
